import hashlib,json,sqlite3,datetime,time,sys
from pathlib import Path
root=Path(sys.argv[1])
before=time.monotonic();c=sqlite3.connect('file:'+str(root/'managed-memory.sqlite')+'?mode=ro',uri=True);c.row_factory=sqlite3.Row
q=lambda sql:[dict(x) for x in c.execute(sql)]
ranks=q('select distinct globalPid,pid from PROCESSES where pid in (726987,726988,726990,726992)')
d={'job':'38537185','source':'ff2572f266d9463c6cb820f883e514387aecd869','scope':'Partial instrumented pressure diagnostic;3 of8updates completed, no checkpoint4. Not throughput, recovery or task qualification.','status':'FAILED semantic completion despite profiler/scheduler exit0; native driver explicitly terminated after backward stall.','trace_origin':q('select * from TARGET_INFO_SESSION_START_TIME'),'learner_pids':ranks,'kernel_coverage':q('select globalPid,count(*) as events,min(start) as first_start_ns,max(end) as last_end_ns from CUPTI_ACTIVITY_KIND_KERNEL group by globalPid'),'optimizer_kernel_coverage':q("select k.globalPid,s.value as kernel,count(*) as events,sum(k.end-k.start) as summed_event_ns,min(k.start) as first_start_ns,max(k.end) as last_end_ns from CUPTI_ACTIVITY_KIND_KERNEL k join StringIds s on k.demangledName=s.id where s.value like '%Optimizer%' or s.value like '%optimizer%' group by k.globalPid,k.demangledName"),'gpu_page_faults':q('select globalPid,deviceId,count(*) as events,sum(numberOfPageFaults) as faults,sum(end-start) as summed_event_ns,min(start) as first_start_ns,max(end) as last_end_ns from CUDA_UM_GPU_PAGE_FAULT_EVENTS group by globalPid,deviceId'),'unified_transfers':q('select globalPid,copyKind,migrationCause,count(*) as events,sum(bytes) as bytes,sum(end-start) as summed_event_ns,min(start) as first_start_ns,max(end) as last_end_ns from CUPTI_ACTIVITY_KIND_MEMCPY where copyKind in (11,12,13) group by globalPid,copyKind,migrationCause'),'transfer_enums':q('select * from ENUM_CUDA_MEMCPY_OPER'),'migration_enums':q('select * from ENUM_CUDA_UNIF_MEM_MIGRATION'),'warnings':q('select severity,text,count(*) as count from DIAGNOSTIC_EVENT where severity in (2,3) group by severity,text'),'later_transfers':{},'limitations':['Optimizer kernels and unified transfers captured for learner rank1 only; other ranks have truncated GPU activity. Never infer zero migration on other ranks.','Summed event durations may overlap and exclude stall/driver overhead; they are not measured critical-path overhead.','All captured transfers precede first checkpoint; later time bins distinguish repeated training migration from only first touches, but do not isolate which individual state arrays moved.','Instrumentation coincides with stalled update4; no OOM traceback in sampled workers. Profiler versus pressure/collective cause unresolved. Uninstrumented paged32 and fresh16to32 passed.','No inference latency, sustained paging speed or total-memory saving inferred. Native memory sampler excludes profiler ancestors.']}
for a,b in [(0,40),(40,70),(70,120)]:
 d['later_transfers'][f'{a}_{b}_seconds_from_trace_origin']=q(f'select globalPid,copyKind,migrationCause,count(*) as events,sum(bytes) as bytes,sum(end-start) as summed_event_ns from CUPTI_ACTIVITY_KIND_MEMCPY where copyKind in (11,12,13) and start>={a}*1000000000 and start<{b}*1000000000 group by globalPid,copyKind,migrationCause')
d['artifacts']={}
for n in ['managed-memory.nsys-rep','managed-memory.sqlite']:
 p=root/n;h=hashlib.sha256()
 with p.open('rb') as f:
  for buf in iter(lambda:f.read(8*1024*1024),b''):h.update(buf)
 d['artifacts'][n]={'bytes':p.stat().st_size,'sha256':h.hexdigest(),'location':str(p)}
d['analysis_seconds']=time.monotonic()-before
(root/'migration-analysis.json').write_text(json.dumps(d,indent=2)+'\n')
print(json.dumps({'artifacts':d['artifacts'],'warnings':d['warnings'],'later_transfers':d['later_transfers'],'analysis_seconds':d['analysis_seconds']},indent=2))
